        <label><span>정렬</span><select id="content-sort"><option value="health" ${e.sortBy==="health"?"selected":""}>진단 점수</option><option value="views" ${e.sortBy==="views"?"selected":""}>조회수</option><option value="recent" ${e.sortBy==="recent"?"selected":""}>최신순</option></select></label>
